// Space office: read-only visual navigation over the existing office records.
(() => {
  const colors=['#a7f3bc','#b6a0ff','#ffcb86','#83d8ff','#ff9dba','#9ce7e3'];
  const titles=['Signal scout','Council core','Draft engineer','Application pilot','Connection radar','Message architect'];
  const roles=['DISCOVERY / 01','EVALUATION / 02','MATERIALS / 03','SUBMISSION / 04','NETWORK / 05','OUTREACH / 06'];
  const modules={
    scout:[['Signal receiver','Read the existing backlog and approved search criteria. Find the specific missing fact that can advance a saved application.'],['Evidence scanner','Verify employer descriptions, pay, season, location, graduation rules and live availability. Preserve unknowns and source limits.'],['Memory bank','Deduplicate by requisition or canonical URL and preserve relevant leads, exclusions and source coverage.'],['Council handoff','Send current candidate and opportunity evidence into an independent council review.']],
    council:[['Evidence intake','Freeze the current candidate and opportunity evidence in a focused review packet.'],['Five perspective cores','Recruiter, Career strategist, Realist, Advocate and Skeptic assess independently. Initial packets do not reveal other votes.'],['Challenge chamber','The same five reviewers examine the initial objections and return actual final votes.'],['Decision gate','All five final approvals and resolved eligibility are required. Preserve disagreements, holds and superseded evidence.']],
    writer:[['Fact memory','Use the approved resume and confirmed candidate facts. Reuse suitable current materials.'],['Language engine','Make truthful light wording and emphasis changes. Preserve resume appearance and protected sections.'],['Field assembler','Include supported education, work, leadership, skills, languages, certifications and optional fields.'],['Audit socket','An independent reviewer checks completeness, omissions and exact document versions before readiness.']],
    operator:[['Permission intake','Check the named destination, data and document permissions, current council and saved answers.'],['Portal interface','One coordinator fills the employer portal, reuses checkpoints and pauses for access or unknown mandatory declarations.'],['Submission gate','Verify eligibility, completeness audit, exact file hashes, declarations, current ready record and live employer state.'],['Delivery recorder','Submit only when every gate passes; record Applied only after an actual employer confirmation.']],
    researcher:[['Opportunity receiver','Connect the company and role to the candidate’s actual background.'],['People radar','Research UMiami alumni, junior team members and genuine shared experiences in that order.'],['Connection verifier','Preserve the profile source and verified common ground. Do not invent a relationship.'],['Contact memory','Store verified contacts and pass their context to the outreach writer.']],
    outreach:[['Context intake','Read the verified contact, opportunity and genuine connection.'],['Message composer','Prepare a relevant coffee-chat request, introduction or follow-up from confirmed facts.'],['Human review gate','Save the exact recipient, channel and message for review. Outreach requires separate authorization.'],['Conversation memory','Record actual contacts and messages; a saved draft is not proof that a message was sent.']]
  };
  let sources=null, sourceError='', activeRobot=null, activeModule=0, deliveryFilter='all', expanded=false, motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const robotIndex=id=>workers.findIndex(w=>w.id===id);
  const countPending=()=>state.approvals.filter(a=>a.status==='pending'&&a.kind==='question').length;
  const confirmed=j=>(j.history||[]).some(h=>h.stage==='Applied'&&h.evidence);
  const submitted=j=>confirmed(j)||['Applied','Interviewing','Offer','Rejected','Withdrawn'].includes(j.stage);
  const approved=j=>j.user_approved||j.council?.startsWith('Approved');
  const appReviews=j=>state.approvals.filter(a=>a.opportunity_id===j.id&&a.kind==='application'&&a.status!=='superseded');
  function delivery(j){
    if(submitted(j))return {group:'finished',step:6,label:j.stage!=='Applied'?j.stage:confirmed(j)?'Submission recorded':'Applied · inspect confirmation',detail:j.next_action||(j.stage==='Applied'?'Application sent':j.stage),blocked:false};
    if(j.council==='Not approved'||j.scout_status==='Excluded')return {group:'unapproved',step:1,label:j.scout_status==='Excluded'?'Excluded by criteria':'Not approved by council',detail:j.next_action,blocked:true};
    const reviews=appReviews(j), current=reviews[reviews.length-1];
    if(current&&['blocked','needs_refresh','changes_requested','withdrawn'].includes(current.status))return {group:'blocked',step:3,label:current.status==='needs_refresh'?'Document refresh needed':'Waiting on an exception',detail:current.body||j.next_action,blocked:true};
    if(j.stage==='Ready for approval'||reviews.some(a=>a.ready&&['pending','approved','ready_auto_submit'].includes(a.status)))return {group:'ready',step:5,label:'Completed draft · awaiting delivery',detail:j.next_action,blocked:false};
    if(j.stage==='Preparing')return {group:'preparing',step:3,label:'Application preparation',detail:j.next_action,blocked:false};
    if(approved(j))return {group:'preparing',step:j.council?.startsWith('Approved')?2:1,label:j.user_approved&&!j.council?.startsWith('Approved')?'User approved · council pending':'Council approved · materials next',detail:j.next_action,blocked:false};
    if(j.council_queue==='reviewing'||j.council==='Needs review')return {group:'unapproved',step:1,label:'Council review / unresolved fit',detail:j.next_action,blocked:j.council==='Needs review'};
    return {group:'unapproved',step:0,label:'Saved lead · not yet approved',detail:j.next_action,blocked:false};
  }
  const counts=()=>state.opportunities.reduce((a,j)=>{a[delivery(j).group]++;return a;},{finished:0,preparing:0,ready:0,blocked:0,unapproved:0});
  function robotSVG(i,cls=''){
    const color=colors[i];
    const extras=[`<path d="M62 19V7h10v8h8v8" fill="none" stroke="${color}" stroke-width="4"/><rect x="66" y="3" width="12" height="8" fill="${color}"/>`,`<path d="M44 18V8h8v10m12 0V4h8v14m12 0V8h8v10" stroke="${color}" stroke-width="4"/>`,`<rect x="92" y="39" width="12" height="20" fill="${color}"/><path d="M96 39l9-9" stroke="${color}" stroke-width="4"/>`,`<path d="M35 30L24 16M96 30l12-14" stroke="${color}" stroke-width="4"/><rect x="20" y="10" width="8" height="8" fill="${color}"/><rect x="105" y="10" width="8" height="8" fill="${color}"/>`,`<path d="M57 18V6h20v12" fill="none" stroke="${color}" stroke-width="4"/><rect x="61" y="2" width="12" height="8" fill="${color}"/>`,`<path d="M39 34H26v21h13m58-21h13v21H97" fill="none" stroke="${color}" stroke-width="4"/>`][i];
    return `<svg class="pixel-robot ${cls}" viewBox="0 0 136 164" aria-hidden="true" shape-rendering="crispEdges"><ellipse cx="68" cy="154" rx="48" ry="7" fill="${color}" opacity=".14"/><g class="robot-float">${extras}<path d="M40 23h56v8h8v37h-8v8H40v-8h-8V31h8z" fill="#243548" stroke="${color}" stroke-width="3"/><path d="M42 34h52v28H42z" fill="#0a1729"/><g class="robot-eyes" fill="${color}"><rect x="49" y="43" width="10" height="9"/><rect x="77" y="43" width="10" height="9"/></g><path d="M59 59h18" stroke="${color}" stroke-width="3"/><path d="M60 78h16v6H60z" fill="#8298b0"/><path d="M42 83h52v45H42z" fill="#263a51" stroke="${color}" stroke-width="3"/><path d="M48 89h40v30H48z" fill="#0a1729"/><rect class="robot-core" x="59" y="96" width="18" height="17" fill="${color}"/><path d="M29 86h9v33H27v-8h2zM98 86h10v25h3v8H98z" fill="#536c82"/><rect class="robot-hand" x="24" y="116" width="15" height="12" fill="${color}"/><rect class="robot-hand other" x="97" y="116" width="15" height="12" fill="${color}"/><path d="M49 132h13v14H44v-7h5zM74 132h13v7h5v7H74z" fill="#7890a5"/><path d="M49 130h13M74 130h13" stroke="${color}" stroke-width="4"/></g></svg>`;
  }
  const stars=()=>Array.from({length:50},(_,i)=>`<i style="left:${(i*47+13)%100}%;top:${(i*31+7)%100}%;--twinkle:${3+i%5}s;--delay:-${i%9}s"></i>`).join('');
  function wireSVG(){return `<svg class="world-wires" viewBox="0 0 1200 640" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="wire-gradient"><stop stop-color="#97e8dc"/><stop offset=".5" stop-color="#a48cff"/><stop offset="1" stop-color="#7bd1f1"/></linearGradient></defs><g class="wire-base"><path d="M250 245H600H950M250 475H600H950M250 245V330H600V475M950 245V330H600M600 475V595"/></g><g class="wire-signal"><path d="M250 245H600H950M250 475H600H950M250 245V330H600V475M950 245V330H600M600 475V595"/></g><g fill="#92bdbb"><circle cx="250" cy="330" r="4"/><circle cx="600" cy="330" r="5"/><circle cx="950" cy="330" r="4"/></g></svg>`;}
  function robotStatus(id){
    const p=state.pipeline||{},jobs=state.opportunities;
    if(id==='scout')return `${jobs.length} saved signals`;
    if(id==='council')return `${jobs.filter(j=>j.council?.startsWith('Approved')).length} council approved`;
    if(id==='writer')return `${jobs.filter(j=>j.stage==='Preparing'&&!submitted(j)).length} in preparation`;
    if(id==='operator')return `${counts().finished} submissions recorded`;
    if(id==='researcher')return `${state.contacts.length} contacts saved`;
    return `${state.approvals.filter(a=>a.kind==='outreach'&&a.status!=='superseded').length} message drafts`;
  }
  function world(){
    const c=counts();
    return `<section class="space-universe" aria-label="Robot space office"><div class="space-stars" aria-hidden="true">${stars()}</div><div class="space-nav"><a class="space-brand" href="/">${robotSVG(0)}<span>User<span class="brand-sub">ORBITAL OFFICE</span></span></a><div class="space-links"><button data-go="office" class="selected">Mission control</button><button data-go="tracker">Opportunities <span>${state.opportunities.length}</span></button><button data-go="approvals">Inbox <span>${countPending()}</span></button><button data-go="candidate">Profile</button><button data-go="pipeline">Flight log</button></div><button class="space-expand" data-space-fullscreen aria-label="Enter fullscreen robot office">⛶ <span>Fullscreen</span></button></div><div class="mission-head"><div><div class="space-kicker"><span></span>SUMMER 2027 / FINANCE & ACCOUNTING</div><h1>Your crew.<br><em>One orbit ahead.</em></h1><p>Six robots. One mission. Your next internship.</p></div><div class="mission-telemetry"><div><span>SUBMITTED TODAY</span><strong>${dailySubmitted()}<small> / 5</small></strong></div><div><span>READY TO DELIVER</span><strong>${c.ready}</strong></div><div><span>NEEDS YOUR INPUT</span><strong>${countPending()}</strong></div></div></div><div class="robot-world"><div class="orbital-planet" aria-hidden="true"></div><span class="orbit-coordinate">SECTOR 27 · UMIAMI</span><span class="world-hint">SELECT A ROBOT TO EXPLORE ITS INNER WORKINGS <span>↘</span></span>${wireSVG()}<div class="robot-grid">${workers.map((w,i)=>`<button class="robot-station" data-worker="${w.id}" style="--robot-color:${colors[i]};--robot-delay:-${i*.7}s" aria-label="Enter ${esc(w.name)} robot"><span class="station-code">${roles[i]}</span><span class="robot-platform">${robotSVG(i)}<span class="platform-ring"></span><span class="platform-floor"></span></span><span class="robot-title">${titles[i]}</span><span class="robot-records">${robotStatus(w.id)}</span><span class="robot-enter">EXPLORE SYSTEM <span>↗</span></span></button>`).join('')}</div><div class="world-note"><span class="status-light"></span><span id="space-runtime">Loading worker status…</span><button data-space-motion aria-pressed="${!motion}">${motion?'Ⅱ Pause animation':'▶ Resume animation'}</button><span>Motion is visual · records reflect saved work</span></div></div><button class="delivery-dock" data-delivery="all"><span class="dock-art" aria-hidden="true"><span class="dock-sign">DELIVERY</span><span class="dock-door"><i></i><i></i><i></i></span><span class="dock-crate"></span><span class="dock-crate second"></span></span><span class="dock-intro"><span class="space-kicker">THE LAST MILE</span><strong>Delivery studio</strong><span>Follow every application from signal to sent.</span></span><span class="dock-numbers"><span><b>${c.finished}</b>FINISHED</span><span><b>${c.preparing+c.ready}</b>IN THE PIPELINE</span><span><b>${c.unapproved+c.blocked}</b>NOT CLEARED</span></span><span class="dock-arrow">↗</span></button><div class="space-foot"><span>YOUR PRIVATE INTERNSHIP UNIVERSE</span><div><button data-go="contacts">Connections</button><button data-space-add>+ Add opportunity</button><button data-space-refresh>↻ Refresh records</button></div></div></section>`;
  }
  office=world;
  const priorRender=render;
  render=function(){document.body.classList.toggle('space-home',view==='office');document.body.classList.add('space-theme');$('#dialog').classList.remove('robot-dialog','delivery-dialog');priorRender();};
  function workRecords(id){
    const jobs=state.opportunities;
    const jobCard=j=>`<button class="work-record" data-job="${esc(j.id)}"><span>${esc(j.company)}</span><small>${esc(j.title)}</small><em>${esc(id==='council'?j.council:delivery(j).label)}</em></button>`;
    if(id==='scout')return `<div class="record-list">${(state.pipeline?.runs||[]).map(r=>`<article class="work-record"><span>${esc(r.origin)} research · ${esc(r.status)}</span><small>${esc(r.summary||'No summary recorded.')}</small><em>${r.imported||0} imported · ${new Date(r.updated).toLocaleDateString()}</em></article>`).join('')||'<p class="empty-record">No research runs recorded.</p>'}</div><button class="secondary" data-worker-view="pipeline">Inspect source coverage →</button>`;
    if(id==='council')return `<div class="record-list">${(state.pipeline?.councils||[]).map(c=>`<button class="work-record" data-council="${esc(c.id)}"><span>${esc(c.opportunity_snapshot.company)}</span><small>${esc(c.current?(c.decision||'Review in progress'):'Superseded evidence')}</small><em>Independent ${c.round1.length}/5 · Challenge ${c.round2.length}/5</em></button>`).join('')||'<p class="empty-record">No council work recorded.</p>'}</div>`;
    if(id==='writer')return `<div class="record-list">${state.approvals.filter(a=>['document','application'].includes(a.kind)&&a.status!=='superseded').slice().reverse().map(a=>`<button class="work-record" data-approval="${esc(a.id)}"><span>${esc(a.title)}</span><small>${esc(a.kind)} · ${esc(a.status.replaceAll('_',' '))}</small><em>${a.ready?'Readiness recorded':'Inspect exact materials and omissions'} →</em></button>`).join('')||'<p class="empty-record">No materials recorded.</p>'}</div>`;
    if(id==='operator')return `<div class="record-list">${jobs.filter(j=>submitted(j)||j.stage==='Preparing'||j.stage==='Ready for approval').map(jobCard).join('')||'<p class="empty-record">No portal work recorded.</p>'}</div><button class="secondary" data-delivery="all">Open delivery studio →</button>`;
    if(id==='researcher')return `<div class="record-list">${state.contacts.map(c=>`<article class="work-record"><span>${esc(c.name)}</span><small>${esc(c.role)} · ${esc(c.connection)}</small><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Verified source ↗</a></article>`).join('')||'<p class="empty-record">No verified contacts recorded yet.</p>'}</div><button class="secondary" data-worker-view="contacts">Open connections →</button>`;
    return `<div class="record-list">${state.approvals.filter(a=>a.kind==='outreach'&&a.status!=='superseded').map(a=>`<button class="work-record" data-approval="${esc(a.id)}"><span>${esc(a.title)}</span><small>${esc(a.recipient)} · ${esc(a.status)}</small><em>Open exact message →</em></button>`).join('')||'<p class="empty-record">No outreach drafts recorded yet.</p>'}</div>`;
  }
  function sourceConsole(id){
    if(!sources)return `<p class="empty-record">${esc(sourceError||'Loading the current source files…')}</p>`;
    const selected=sources.sources.filter(s=>id==='council'||s.id!=='review-packet');
    const headings={scout:['Application-first decisions','Scout: discover, verify, import'],council:['Candidate facts and review reuse','Council: five independent assessments plus challenge'],writer:['Overnight applications and fewer interruptions','Applications: complete, truthful and permission-bound'],operator:['Overnight applications and fewer interruptions','Applications: complete, truthful and permission-bound','Replies, reporting and recovery']};
    const workflow=sources.sources.find(s=>s.id==='WORKFLOW.md');
    const excerpts=(workflow?.body||'').split(/\n(?=## )/).filter(part=>(headings[id]||[]).some(h=>part.startsWith('## '+h))).join('\n\n');
    return `<p class="source-explanation">${esc(sources.notice)}</p>${['researcher','outreach','scout'].includes(id)?'<p class="source-explanation">The cloud worker is application-only. This robot’s general discovery or outreach is not enabled by that runtime prompt.</p>':''}${excerpts?`<details class="source-file" open><summary><span>This robot’s operating instructions</span><small>Exact excerpts from WORKFLOW.md</small></summary><pre>${esc(excerpts)}</pre></details>`:''}${selected.map(s=>`<details class="source-file"><summary><span>${esc(s.title)}</span><small>${esc(s.kind)}</small></summary><div class="source-meta">${esc(s.location)}${s.sha256?` · SHA-256 ${s.sha256.slice(0,12)}`:''}</div><pre>${esc(s.body)}</pre></details>`).join('')}`;
  }
  function robotBody(id,module=0){
    activeRobot=id;activeModule=module;
    const i=robotIndex(id),w=workers[i],parts=modules[id],part=parts[module];
    modal(`<div class="robot-inspection" style="--robot-color:${colors[i]}"><div class="inspection-head"><div><div class="space-kicker">ROBOT ${String(i+1).padStart(2,'0')} / INTERNAL SYSTEMS</div><h2>${titles[i]}</h2><p>${esc(w.name)} · ${esc(robotStatus(id))}</p></div><button class="secondary" data-space-return>↙ Back to orbit</button></div><div class="inspection-grid"><section class="robot-anatomy" aria-label="${esc(w.name)} workflow"><div class="anatomy-head">${robotSVG(i)}<span>SELECT A COMPONENT</span></div><div class="anatomy-shell"><div class="shell-bolts" aria-hidden="true"></div>${parts.map((p,n)=>`<button class="module-node ${module===n?'selected':''}" data-robot-module="${n}" aria-label="Inspect ${esc(p[0])}" aria-pressed="${module===n}"><span class="module-chip">${['◈','▤','⟁','⇄'][n]}</span><span><small>MODULE ${n+1}</small><b>${esc(p[0])}</b></span><em>↗</em></button>`).join('')}<div class="anatomy-feet" aria-hidden="true"><i></i><i></i></div></div><p class="anatomy-note">Wires show the handoff order.<br>Open a component to inspect its rules.</p></section><section class="system-detail"><div class="space-kicker">COMPONENT ${module+1} / ${parts.length}</div><h3>${esc(part[0])}</h3><p class="component-purpose">${esc(part[1])}</p><div class="system-tabs"><button class="active" data-system-tab="work">Recorded work</button><button data-system-tab="sources">Prompts & rules</button></div><div id="robot-work"><div class="system-label">SAVED OUTPUT OF THIS ROBOT</div>${workRecords(id)}</div><div id="robot-sources" hidden>${sourceConsole(id)}</div></section></div></div>`);
    $('#dialog').classList.add('robot-dialog');
  }
  worker=id=>robotBody(id);
  function deliveryRow(j){
    const d=delivery(j),steps=['Signal','Council','Materials','Form','Audit','Ready','Sent'];
    const reviews=appReviews(j),ready=reviews.some(a=>a.ready&&['pending','approved','ready_auto_submit','submitted'].includes(a.status));
    const council=j.council?.startsWith('Approved')||(submitted(j)&&(j.prior_council||[]).some(c=>c.council?.startsWith('Approved')));
    const marked=[true,council,(j.documents||[]).length>0||reviews.some(a=>Object.keys(a.documents||{}).length),ready,ready,ready,submitted(j)];
    return `<article class="shipment"><div class="shipment-title"><span class="shipment-monogram">${esc(j.company[0])}</span><div><h3>${esc(j.company)}</h3><p>${esc(j.title)}</p></div><span class="shipment-state ${d.group}">${esc(d.label)}</span></div><ol class="shipment-track" aria-label="Application progress">${steps.map((s,i)=>`<li class="${marked[i]?'done ':''}${i===d.step?'current':''}" aria-label="${s}: ${i===d.step?'current saved phase':marked[i]?'recorded':'not separately recorded'}"><span>${marked[i]?'✓':String(i+1).padStart(2,'0')}</span><small>${s}</small></li>`).join('')}</ol><div class="shipment-bottom"><p><b>Next step</b> ${esc(d.detail||j.next_action||'Review the saved application record.')}</p><button class="secondary" data-job="${esc(j.id)}">Open record ↗</button></div><div class="shipment-evidence">${confirmed(j)?'Submission evidence saved':submitted(j)?'Outcome recorded · inspect history for confirmation':'This is saved progress; no live delivery is inferred.'}${j.user_approved?' · User approved':''}${j.council?.startsWith('Approved')?' · Council approved':''}</div></article>`;
  }
  function studio(filter='all'){
    deliveryFilter=filter;activeRobot=null;
    const c=counts(),filters=[['all','All cargo',state.opportunities.length],['finished','Finished',c.finished],['preparing','In preparation',c.preparing],['ready','Ready to deliver',c.ready],['blocked','Blocked',c.blocked],['unapproved','Not approved',c.unapproved]];
    const jobs=state.opportunities.filter(j=>filter==='all'||delivery(j).group===filter).sort((a,b)=>({ready:0,preparing:1,blocked:2,unapproved:3,finished:4}[delivery(a).group]-{ready:0,preparing:1,blocked:2,unapproved:3,finished:4}[delivery(b).group]));
    modal(`<div class="studio-head"><div class="space-kicker">ORBITAL DELIVERY STUDIO / APPLICATION MANIFEST</div><h2>From your crew to your career.</h2><p>Finished applications, saved preparation, and everything still waiting to clear a gate.</p></div><div class="studio-stats"><div><strong>${c.finished}</strong><span>Submission records</span></div><div><strong>${c.ready}</strong><span>Completed drafts</span></div><div><strong>${c.preparing}</strong><span>Preparation queue</span></div><div><strong>${c.blocked+c.unapproved}</strong><span>Not cleared</span></div></div><div class="studio-filters" role="group" aria-label="Filter application deliveries">${filters.map(([f,label,count])=>`<button data-delivery="${f}" class="${f===filter?'active':''}" aria-pressed="${f===filter}">${label}<span>${count}</span></button>`).join('')}</div><p class="studio-legend">Checks show recorded milestones; blue marks the current saved phase. Unmarked steps are not separately recorded. “Ready” is a completed draft; “Sent” requires a submission record. Saved progress does not imply a live transmission.</p><div class="shipment-list">${jobs.map(deliveryRow).join('')||'<div class="empty-record">No applications in this bay yet.</div>'}</div>`);
    $('#dialog').classList.add('delivery-dialog');
  }
  async function getSources(){try{sources=await api('/api/robot-sources');sourceError='';}catch(e){sourceError='The server cannot provide prompt sources yet. '+e.message;}
    if(activeRobot&&$('#dialog').open&&$('#robot-sources'))$('#robot-sources').innerHTML=sourceConsole(activeRobot);
    updateRuntime();
  }
  function updateRuntime(){const el=$('#space-runtime');if(el)el.textContent=sources?`SERVER WORKER ${sources.runtime.enabled?'ENABLED':'DISABLED'} · SAVED ACTIVITY`:sourceError?'WORKER STATUS UNAVAILABLE':'Loading worker status…';setExpanded(expanded);}
  function setExpanded(value){expanded=value;document.body.classList.toggle('space-expanded',value);const b=$('[data-space-fullscreen]');if(b){b.innerHTML=value?'↙ <span>Exit fullscreen</span>':'⛶ <span>Fullscreen</span>';b.setAttribute('aria-label',value?'Exit fullscreen robot office':'Enter fullscreen robot office');}}
  window.officeMotion={mount(){document.body.classList.toggle('space-motion-paused',!motion||document.hidden);updateRuntime();}};
  document.addEventListener('click',async e=>{
    const node=e.target.closest('[data-robot-module],[data-system-tab],[data-delivery],[data-space-return],[data-space-fullscreen],[data-space-motion],[data-space-add],[data-space-refresh]');if(!node)return;
    if(node.dataset.robotModule!==undefined&&activeRobot)robotBody(activeRobot,Number(node.dataset.robotModule));
    if(node.dataset.systemTab){const prompt=node.dataset.systemTab==='sources';$('#robot-work').hidden=prompt;$('#robot-sources').hidden=!prompt;document.querySelectorAll('[data-system-tab]').forEach(b=>b.classList.toggle('active',b===node));}
    if(node.dataset.delivery!==undefined)studio(node.dataset.delivery);
    if(node.hasAttribute('data-space-return'))close();
    if(node.hasAttribute('data-space-add'))addJob();
    if(node.hasAttribute('data-space-refresh')){await load();await getSources();}
    if(node.hasAttribute('data-space-motion')){motion=!motion;document.body.classList.toggle('space-motion-paused',!motion);node.textContent=motion?'Ⅱ Pause animation':'▶ Resume animation';node.setAttribute('aria-pressed',!motion);}
    if(node.hasAttribute('data-space-fullscreen')){if(expanded){if(document.fullscreenElement)await document.exitFullscreen();setExpanded(false);}else{setExpanded(true);try{await document.documentElement.requestFullscreen();}catch{message('Expanded office view. Browser fullscreen is unavailable here; press Escape to return.');}}}
  });
  document.addEventListener('fullscreenchange',()=>setExpanded(!!document.fullscreenElement));
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&expanded&&!$('#dialog').open&&!document.fullscreenElement)setExpanded(false);});
  document.addEventListener('visibilitychange',()=>document.body.classList.toggle('space-motion-paused',!motion||document.hidden));
  reduced.addEventListener('change',e=>{motion=!e.matches;document.body.classList.toggle('space-motion-paused',!motion);const b=$('[data-space-motion]');if(b){b.textContent=motion?'Ⅱ Pause animation':'▶ Resume animation';b.setAttribute('aria-pressed',!motion);}});
  window.spaceOffice={delivery,counts,robotBody,studio};
  getSources();
})();
